using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using StudentAccommodationSystem.Data; using StudentAccommodationSystem.Models; using StudentAccommodationSystem.ViewModels;
namespace StudentAccommodationSystem.Controllers;
[Authorize(Roles="Student")] public class StudentController(ApplicationDbContext db,UserManager<ApplicationUser> users):Controller
{ public async Task<IActionResult> Index(){var u=await users.GetUserAsync(User);if(u==null)return Challenge();var s=await db.StudentProfiles.FirstOrDefaultAsync(x=>x.UserId==u.Id);if(s==null){s=new StudentProfile{UserId=u.Id};db.StudentProfiles.Add(s);await db.SaveChangesAsync();}var vm=new DashboardVm{PendingBookings=await db.Bookings.CountAsync(x=>x.StudentProfileId==s.Id&&x.Status==BookingStatus.Pending),ActiveAgreements=await db.RentalAgreements.CountAsync(x=>x.StudentProfileId==s.Id&&x.Status==AgreementStatus.Active),PendingMaintenance=await db.MaintenanceRequests.CountAsync(x=>x.StudentProfileId==s.Id&&x.Status!=MaintenanceStatus.Closed&&x.Status!=MaintenanceStatus.Resolved)};return View(vm);}}
